function validate([hour, minutes]) {
  if (!Number.isInteger(hour) || hour < 1 || hour > 12) return 'hour is a whole number from 1 to 12.';
  if (!Number.isInteger(minutes) || minutes < 0 || minutes > 59) return 'minutes is a whole number from 0 to 59.';
  return null;
}

