function angleClock(hour, minutes) {
  const minuteAngle = minutes * 6;
  const hourMark = (hour % 12) * 30;
  const hourAngle = hourMark + minutes * 0.5;
  const gap = Math.abs(hourAngle - minuteAngle);
  const otherWay = 360 - gap;
  return Math.min(gap, otherWay);
}

