function angleClock(hour, minutes) {
  // Tick the clock forward from 12:00 one minute at a time, measuring in half degrees.
  let hourPos = 0;
  let minutePos = 0;
  const ticks = (hour % 12) * 60 + minutes;
  for (let t = 0; t < ticks; t++) {
    hourPos = (hourPos + 1) % 720;
    minutePos = (minutePos + 12) % 720;
  }
  // Walk clockwise from the hour hand until reaching the minute hand.
  let steps = 0;
  for (let p = hourPos; p !== minutePos; p = (p + 1) % 720) steps++;
  return Math.min(steps, 720 - steps) / 2;
}

